<script setup lang="ts">
import{onMounted,ref}from"vue";import{ElMessageBox}from"element-plus";import{api}from"../utils/api";
import { useClientPagination } from "../composables/useClientPagination";
const EMPLOYEE_STATUS={ACTIVE:0,INACTIVE:1}as const;const employeeStatusLabels:Record<number,string>={0:"\u5728\u804c",1:"\u505c\u7528"};
const periods=ref<any[]>([]),employees=ref<any[]>([]),items=ref<any[]>([]),salaries=ref<any[]>([]),accounts=ref<any[]>([]),summary=ref<any>({}),periodId=ref<number | "">(""),loading=ref(false),employeeDialog=ref(false),itemDialog=ref(false),employeeId=ref<number | "">(""),itemId=ref<number | "">("");
const {page,pageSize,total,pagedRows: pagedSalaries,resetPage}=useClientPagination(salaries);
const employee=ref<any>({employeeNo:"",name:"",baseSalary:"0",socialInsurance:"0",housingFund:"0",status:EMPLOYEE_STATUS.ACTIVE}),item=ref<any>({code:"",name:"",category:"BONUS",defaultAmount:"0",enabled:true}),accountForm=ref({expenseAccountId:"" as number | "",payableAccountId:"" as number | ""});
async function load(){if(!periodId.value)return;loading.value=true;try{[salaries.value,summary.value]=await Promise.all([api.get<any[]>("/salaries/"+periodId.value),api.get("/salaries/"+periodId.value+"/summary")]);}finally{loading.value=false;}}
async function support(){[periods.value,employees.value,items.value,accounts.value]=await Promise.all([api.get<any[]>("/accounting-periods"),api.get<any[]>("/salaries/employees"),api.get<any[]>("/salaries/items"),api.get<any[]>("/accounts?tree=false")]);if(!periodId.value&&periods.value[0]){periodId.value=periods.value[0].id;await load();}}
async function generate(){await api.post("/salaries/"+periodId.value+"/generate",accountForm.value);await load();}
function openEmployee(row?:any){employeeId.value=row?.id??"";employee.value=row?{...row,baseSalary:String(row.baseSalary),socialInsurance:String(row.socialInsurance),housingFund:String(row.housingFund)}:{employeeNo:"",name:"",baseSalary:"0",socialInsurance:"0",housingFund:"0",status:EMPLOYEE_STATUS.ACTIVE};employeeDialog.value=true;}
async function saveEmployee(){if(employeeId.value)await api.put("/salaries/employees/"+employeeId.value,employee.value);else await api.post("/salaries/employees",employee.value);employeeDialog.value=false;await support();}
function openItem(row?:any){itemId.value=row?.id??"";item.value=row?{...row,defaultAmount:String(row.defaultAmount)}:{code:"",name:"",category:"BONUS",defaultAmount:"0",enabled:true};itemDialog.value=true;}
async function saveItem(){if(itemId.value)await api.put("/salaries/items/"+itemId.value,item.value);else await api.post("/salaries/items",item.value);itemDialog.value=false;await support();}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await api.uploadWithFields("/salaries/"+periodId.value+"/import",file,accountForm.value);await load();}
function exportFile(){return api.download("/salaries/"+periodId.value+"/export","salary-"+periodId.value+".xlsx");}async function cancelSalary(row:any){const{value}=await ElMessageBox.prompt("请输入撤销原因","撤销工资计提",{inputPattern:/\S+/,inputErrorMessage:"原因不能为空"});await api.post("/salaries/records/"+row.id+"/cancel",{reason:value});await load();}onMounted(support);
</script>
<template><div class="page-grid"><section class="page-heading"><div><h2>工资管理</h2><p>工资单、工资项目、Excel 导入导出及自动凭证。</p></div><div><el-button @click="openEmployee()">新增员工</el-button><el-button @click="openItem()">新增工资项目</el-button></div></section><el-card shadow="never"><div class="toolbar"><el-select v-model="periodId" style="width:150px" @change="resetPage(); load()"><el-option v-for="p in periods" :key="p.id" :label="p.periodCode" :value="p.id"/></el-select><el-select v-model="accountForm.expenseAccountId" filterable placeholder="工资费用科目" style="width:210px"><el-option v-for="a in accounts" :key="a.id" :label="a.code+' '+a.name" :value="a.id"/></el-select><el-select v-model="accountForm.payableAccountId" filterable placeholder="应付工资科目" style="width:210px"><el-option v-for="a in accounts" :key="a.id" :label="a.code+' '+a.name" :value="a.id"/></el-select><el-button type="primary" @click="generate">生成工资</el-button><label class="el-button"><input type="file" accept=".xlsx" hidden @change="importFile"/>导入 Excel</label><el-button @click="exportFile">导出 Excel</el-button></div></el-card><section class="summary-grid"><el-card shadow="never"><div class="metric-label">员工数</div><strong>{{summary.employeeCount??0}}</strong></el-card><el-card shadow="never"><div class="metric-label">应发合计</div><strong>{{summary.grossAmount??0}}</strong></el-card><el-card shadow="never"><div class="metric-label">实发合计</div><strong>{{summary.netAmount??0}}</strong></el-card></section><el-card shadow="never"><el-table table-layout="auto" v-loading="loading" :data="pagedSalaries" stripe><el-table-column prop="employee.employeeNo" label="编号"/><el-table-column prop="employee.name" label="姓名"/><el-table-column prop="baseSalary" label="基本工资"/><el-table-column prop="bonus" label="奖金"/><el-table-column prop="allowance" label="补贴"/><el-table-column prop="deduction" label="扣款"/><el-table-column prop="socialInsurance" label="社保"/><el-table-column prop="housingFund" label="公积金"/><el-table-column prop="individualIncomeTax" label="个税"/><el-table-column prop="grossAmount" label="应发"/><el-table-column prop="netAmount" label="实发"/><el-table-column prop="voucher.voucherNo" label="凭证号"/><el-table-column label="状态"><template #default="scope">{{scope.row.status===2?'已记账':'已撤销'}}</template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button v-if="scope.row.status===2" text type="danger" @click="cancelSalary(scope.row)">撤销</el-button></template></el-table-column></el-table><PaginationBar v-model:page="page" v-model:page-size="pageSize" :total="total"/></el-card><div class="two-column"><el-card shadow="never"><template #header><b>员工</b></template><el-table table-layout="auto" :data="employees" size="small"><el-table-column prop="employeeNo" label="编号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="baseSalary" label="基本工资"/><el-table-column label="状态"><template #default="scope">{{ employeeStatusLabels[scope.row.status] ?? scope.row.status }}</template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button text @click="openEmployee(scope.row)">编辑</el-button></template></el-table-column></el-table></el-card><el-card shadow="never"><template #header><b>工资项目</b></template><el-table table-layout="auto" :data="items" size="small"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="category" label="类别"/><el-table-column prop="defaultAmount" label="金额"/><el-table-column label="操作"><template #default="scope"><el-button text @click="openItem(scope.row)">编辑</el-button></template></el-table-column></el-table></el-card></div></div>
<el-dialog v-model="employeeDialog" :title="employeeId?'编辑员工':'新增员工'" width="460px"><el-form label-width="90px"><el-form-item label="员工编号"><el-input v-model="employee.employeeNo"/></el-form-item><el-form-item label="姓名"><el-input v-model="employee.name"/></el-form-item><el-form-item label="基本工资"><el-input v-model="employee.baseSalary"/></el-form-item><el-form-item label="社保"><el-input v-model="employee.socialInsurance"/></el-form-item><el-form-item label="公积金"><el-input v-model="employee.housingFund"/></el-form-item><el-form-item label="状态"><el-switch v-model="employee.status" :active-value="EMPLOYEE_STATUS.ACTIVE" :inactive-value="EMPLOYEE_STATUS.INACTIVE"/></el-form-item></el-form><template #footer><el-button @click="employeeDialog=false">取消</el-button><el-button type="primary" @click="saveEmployee">保存</el-button></template></el-dialog>
<el-dialog v-model="itemDialog" :title="itemId?'编辑工资项目':'新增工资项目'" width="460px"><el-form label-width="90px"><el-form-item label="编码"><el-input v-model="item.code"/></el-form-item><el-form-item label="名称"><el-input v-model="item.name"/></el-form-item><el-form-item label="类别"><el-select v-model="item.category"><el-option label="奖金" value="BONUS"/><el-option label="补贴" value="ALLOWANCE"/><el-option label="扣款" value="DEDUCTION"/><el-option label="社保" value="SOCIAL_INSURANCE"/><el-option label="公积金" value="HOUSING_FUND"/></el-select></el-form-item><el-form-item label="默认金额"><el-input v-model="item.defaultAmount"/></el-form-item><el-form-item label="启用"><el-switch v-model="item.enabled"/></el-form-item></el-form><template #footer><el-button @click="itemDialog=false">取消</el-button><el-button type="primary" @click="saveItem">保存</el-button></template></el-dialog></template>
